  1003→        self.osaka = self.client.chain_spec().is_osaka_active_at_timestamp(timestamp);
  1004→        self.max_blob_count = self
  1005→            .client
  1006→            .chain_spec()
  1007→            .blob_params_at_timestamp(timestamp)
  1008→            .unwrap_or_else(BlobParams::cancun)
