    15→pub fn validate_block_post_execution<B, R, ChainSpec>(
    16→    block: &RecoveredBlock<B>,
    17→    chain_spec: &ChainSpec,
    18→    receipts: &[R],
    19→    requests: &Requests,
    20→) -> Result<(), ConsensusError>
