    60→pub struct EthTransactionValidator<Client, T> {
    61→    /// This type fetches account info from the db
    62→    client: Client,
    63→    /// Blobstore used for fetching re-injected blob transactions.
    64→    blob_store: Box<dyn BlobStore>,
