   576→                    let mut buf: &[u8] = decompressed;
   577→                    let (tx_type, new_buf) = T::from_compact(buf, flags.tx_type_len() as usize);
   578→                    buf = new_buf;
   579→                    let (success, new_buf) = bool::from_compact(buf, flags.success_len() as usize);
