   583→                    buf = new_buf;
   584→                    let (logs, _) = Vec::from_compact(buf, buf.len());
   585→                    (Self { tx_type, success, cumulative_gas_used, logs }, original_buf)
   586→                })
   587→            } else {
   588→                let (tx_type, new_buf) = T::from_compact(buf, flags.tx_type_len() as usize);
