   491→    use super::*;
   492→    use reth_codecs::{
   493→        Compact,
   494→        __private::{modular_bitfield::prelude::*, Buf},
   495→    };
   496→
   497→    impl Receipt {
   498→        #[doc = "Used bytes by [`ReceiptFlags`]"]
