   509→    mod flags {
   510→        use super::*;
   511→
   512→        #[doc = "Fieldset that facilitates compacting the parent type. Used bytes: 1 | Unused bits: 0"]
   513→        #[bitfield]
   514→        #[derive(Clone, Copy, Debug, Default)]
   515→        pub struct ReceiptFlags {
   516→            pub tx_type_len: B2,
   517→            pub success_len: B1,
