    58→        let requests_hash = requests.requests_hash();
    59→        if requests_hash != header_requests_hash {
    60→            return Err(ConsensusError::BodyRequestsHashDiff(
    61→                GotExpected::new(requests_hash, header_requests_hash).into(),
