   295→            Self::GetBlockHeaders(_) => EthMessageID::GetBlockHeaders,
   296→            Self::BlockHeaders(_) => EthMessageID::BlockHeaders,
   297→            Self::GetBlockBodies(_) => EthMessageID::GetBlockBodies,
